      d.channels.forEach(c=>{const li=document.createElement('li');li.dataset.channelId=c.id;li.dataset.channelName=c.name;li.className='channel-entry';li.textContent='# '+c.name;li.onclick=()=>select(c);list.appendChild(li)});
      if(d.channels[0]) select(d.channels[0]);
    } catch(e){ showAuth(); }
  }
  async function select(c){channel=c; $('[data-testid=channel-title]').textContent='# '+c.name; $('[data-testid=channel-topic]').textContent=c.topic||''; try{const d=await api('/channels/'+c.id+'/messages'); render(d.messages)}catch(e){}}
  function render(ms){const box=$('[data-testid=message-list]');box.innerHTML=''; if(!ms.length){box.innerHTML='<div class="empty-copy">No messages yet. Start the conversation.</div>';return} ms.slice().reverse().forEach(m=>{const row=document.createElement('div');row.dataset.testid='message';row.className='message';row.innerHTML='<strong>'+esc(m.author.display_name||m.author.username)+'</strong> <time>'+new Date(m.created_at).toLocaleString()+'</time><div data-testid="message-body">'+esc(m.body)+'</div>';box.appendChild(row)})}
