 while True:
  await asyncio.sleep(.1)
  for cid, rows in list(CLIENTS.items()):
   es=db.connect()
   for e in es.execute("SELECT * FROM events WHERE channel_id=? AND event_id>? ORDER BY event_id",(cid, getattr(broadcast_loop,'last',{}).get(cid,0))):
    try:
     import json
     data=json.loads(e['payload']);m=data.get('message',{})
     if e['kind']=='message.created' and m:
      au=es.execute('SELECT username FROM users WHERE id=?',(m.get('author_id'),)).fetchone()
      if au:
       for writer,nick in list(rows):
        try:
         target=es.execute('SELECT w.slug,c.name FROM channels c JOIN workspaces w ON w.id=c.workspace_id WHERE c.id=?',(cid,)).fetchone()
         if target: await send(writer,f':{au[0]}!{au[0]}@huddle PRIVMSG #{target[0]}/{target[1]} :{m.get("body","")}')
        except: pass
     if not hasattr(broadcast_loop,'last'): broadcast_loop.last={}
     broadcast_loop.last[cid]=e['event_id']
    except: pass
   es.close()""")
s=s.replace("    joined[cid]=target\n    await send(w,f':{nick}!{uid}@huddle JOIN {target}')", """    joined[cid]=target
    CLIENTS.setdefault(cid,[]).append((w,nick))
    await send(w,f':{nick}!{uid}@huddle JOIN {target}')
    if x['topic']: await send(w,f'332 {nick} {target} :{x["topic"]}')
    else: await send(w,f'331 {nick} {target} :No topic is set')""")
s=s.replace("  if nick:NICKS.pop(nick.lower(),None)", """  if nick:NICKS.pop(nick.lower(),None)
  for cid in list(joined):
   CLIENTS[cid]=[(ww,nn) for ww,nn in CLIENTS.get(cid,[]) if ww is not w]
   if not CLIENTS[cid]: CLIENTS.pop(cid,None)""")
s=s.replace("async def main():\n s=await asyncio.start_server(handle_client,'0.0.0.0',6667)\n async with s:await s.serve_forever()", """async def main():
 s=await asyncio.start_server(handle_client,'0.0.0.0',6667)
 asyncio.create_task(broadcast_loop())
 async with s:await s.serve_forever()""")
open(p,'w').write(s)
